"""Encoders that turn interleaved stereo PCM16 into a call-recording file."""

from __future__ import annotations

import wave
from pathlib import Path


class WavEncoder:
    """Write interleaved stereo PCM16 as a WAV file."""

    CONTENT_TYPE = "audio/wav"
    FILE_EXTENSION = "wav"

    def encode(self, pcm_path: Path, output_path: Path, sample_rate: int) -> None:
        pcm = pcm_path.read_bytes()
        # wave.open(..., "wb") is typed as Wave_read | Wave_write; construct
        # Wave_write directly so static checkers see the write API.
        with wave.Wave_write(str(output_path)) as wav_file:
            wav_file.setnchannels(2)
            wav_file.setsampwidth(2)
            wav_file.setframerate(sample_rate)
            wav_file.writeframes(pcm)


# Default is WavEncoder (stdlib). Swap to WebmOpusEncoder when ffmpeg is available.
RecordingEncoder = WavEncoder
RECORDING_CONTENT_TYPE = RecordingEncoder.CONTENT_TYPE
RECORDING_FILE_EXTENSION = RecordingEncoder.FILE_EXTENSION
